import{c as s,Z as o,Q as l,j as d,g as t,n,o as r,av as c,m as h}from"./chunks/framework.BwfbE4MI.js";const v=JSON.parse('{"title":"SMS the provider when a new transaction is initiated","description":"","frontmatter":{"title":"SMS the provider when a new transaction is initiated","description":""},"headers":[],"relativePath":"templates/transactions/sms-provider-on-new-transaction.md","filePath":"templates/transactions/sms-provider-on-new-transaction.md","lastUpdated":1779859199000}'),p={name:"templates/transactions/sms-provider-on-new-transaction.md"};function m(u,e,w,f,g,S){const i=o("TemplateActions"),a=o("ClientOnly");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"sms-the-provider-when-a-new-transaction-is-initiated",tabindex:"-1"},[n("SMS the provider when a new transaction is initiated "),t("a",{class:"header-anchor",href:"#sms-the-provider-when-a-new-transaction-is-initiated","aria-label":'Permalink to "SMS the provider when a new transaction is initiated"'},"​")],-1)),e[1]||(e[1]=t("p",null,[t("strong",null,"Category:"),n(),t("a",{href:"/n8n-nodes-sharetribe-docs/templates/transactions/"},"Transactions")],-1)),r(a,null,{default:c(()=>[r(i,{slug:"sms-provider-on-new-transaction",category:"transactions","source-url":"https://github.com/tribebuilder/n8n-nodes-sharetribe/blob/main/workflows/public-templates/published/transactions/sms-provider-on-new-transaction.json"})]),_:1}),e[2]||(e[2]=h('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>A Sharetribe trigger fires whenever a new transaction is initiated on the marketplace.</li><li>The marketplace name is fetched from Sharetribe and merged with the transaction event.</li><li>The full transaction is retrieved with <code>provider</code>, <code>customer</code>, <code>listing</code>, <code>booking</code>, <code>payinTotal</code>, and <code>payoutTotal</code>.</li><li><strong>Prepare Provider SMS Fields</strong> flattens and formats everything the SMS needs: listing title, customer name, provider phone, booking times in the listing&#39;s timezone, payin/payout as money strings, and the <code>transactionProcessName</code>.</li><li><strong>Provider Has Phone Number?</strong> drops transactions where the provider has no phone on file.</li><li><strong>Route By Process Name</strong> Switch sends each item to the matching <strong>Build * SMS</strong> Set node, which sets <code>smsBody</code>.</li><li>Twilio sends <code>smsBody</code> to the provider&#39;s phone.</li></ol><h2 id="setup-steps" tabindex="-1">Setup steps <a class="header-anchor" href="#setup-steps" aria-label="Permalink to &quot;Setup steps&quot;">​</a></h2><ul><li><ul><li>[ ] Connect your Sharetribe credentials to the trigger and all Sharetribe action nodes.</li></ul></li><li><ul><li>[ ] Connect your Twilio account credentials to the <strong>Send SMS To Provider</strong> node and set the <code>From</code> number.</li></ul></li><li><ul><li>[ ] Confirm your provider profiles store phone numbers at <code>profile.protectedData.phoneNumber</code>. If not, update the <code>to</code> expression on the Twilio node.</li></ul></li><li><ul><li>[ ] Configure an error workflow under this workflow&#39;s Settings so failed runs alert you instead of silently dropping notifications.</li></ul></li><li><ul><li>[ ] Open each <strong>Build * SMS</strong> Set node and tweak the <code>smsBody</code> template to taste.</li></ul></li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Sharetribe marketplace with Integration API credentials</li><li>Twilio account with an SMS-capable phone number</li><li>Provider phone numbers stored on the user profile (typically <code>protectedData.phoneNumber</code>)</li></ul><h2 id="customization" tabindex="-1">Customization <a class="header-anchor" href="#customization" aria-label="Permalink to &quot;Customization&quot;">​</a></h2><p>Swap Twilio for MessageBird, Vonage, or another SMS provider supported by n8n. Edit <strong>Prepare Provider SMS Fields</strong> to add fields or change how money and dates are formatted. Edit any of the four <strong>Build * SMS</strong> Set nodes to change wording or rearrange lines for that process type. Add a second SMS node to also notify the customer.</p><p>Need help? Visit the <a href="https://community.n8n.io/" target="_blank" rel="noreferrer">n8n Community</a> or <a href="https://www.sharetribe.com/docs/" target="_blank" rel="noreferrer">Sharetribe Docs</a>.</p><div class="tip custom-block"><p class="custom-block-title">Recommended</p><p>Set up an <a href="https://docs.n8n.io/flow-logic/error-handling/" target="_blank" rel="noreferrer">error workflow</a> so you&#39;re notified if anything goes wrong - the same step applies to any n8n workflow you run in production.</p></div><p><a href="/n8n-nodes-sharetribe-docs/templates/transactions/">← Back to Transactions</a> · <a href="/n8n-nodes-sharetribe-docs/templates">All workflow templates</a></p>',11))])}const y=s(p,[["render",m]]);export{v as __pageData,y as default};
